insert into materiais (turma_id, autor, materia, titulo, status, questoes, publicado_em)
select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'hi', 'Idade Média e feudalismo', 'publicado', $j$[{"id": "q1", "tipo": "mc", "enunciado": "Qual acontecimento marca o <b>início</b> da Idade Média?", "resposta": "a queda do Império Romano do Ocidente (476)", "alternativas": ["a queda do Império Romano do Ocidente (476)", "a tomada de Constantinopla pelos turcos (1453)", "a invenção da escrita", "a chegada dos portugueses ao Brasil (1500)"], "explicacao": "Em 476, o Império Romano do Ocidente caiu e começou a Idade Média.", "tutor": {"alternativas": {"a tomada de Constantinopla pelos turcos (1453)": "Essa data marca o FIM da Idade Média, não o começo.", "a invenção da escrita": "A escrita marca o fim da Pré-história, milhares de anos antes.", "a chegada dos portugueses ao Brasil (1500)": "1500 já é Idade Moderna, depois do fim da Idade Média."}, "pontos": ["Idade Média: de 476 (queda de Roma no Ocidente) a 1453 (tomada de Constantinopla).", "São cerca de mil anos de História."], "pegadinha": "476 abre e 1453 fecha. Muita gente troca as duas datas."}}, {"id": "q2", "tipo": "mc", "enunciado": "No feudalismo, o <b>feudo</b> era:", "resposta": "uma grande propriedade de terra", "alternativas": ["uma grande propriedade de terra", "um imposto pago à Igreja", "uma cidade-Estado independente", "um tipo de navio usado no comércio"], "explicacao": "O feudo era uma grande propriedade de terra, a principal riqueza da época.", "tutor": {"alternativas": {"um imposto pago à Igreja": "O imposto pago à Igreja era o dízimo.", "uma cidade-Estado independente": "Cidade-Estado é a pólis grega, de outra época.", "um tipo de navio usado no comércio": "O feudalismo era rural; o feudo era terra, não navio."}, "pontos": ["Feudo = terra. Quem tinha terra tinha poder.", "No feudo havia o castelo do senhor, as terras dos servos e áreas de uso comum."], "pegadinha": "Feudo não é o castelo: o castelo ficava dentro do feudo."}}, {"id": "q3", "tipo": "mc", "enunciado": "Na relação de suserania e vassalagem, o <b>vassalo</b>:", "resposta": "recebia terras e jurava fidelidade e ajuda militar", "alternativas": ["recebia terras e jurava fidelidade e ajuda militar", "era o camponês que trabalhava na terra", "era quem concedia o feudo", "era o padre que cobrava o dízimo"], "explicacao": "O vassalo recebia um feudo do suserano e, em troca, prometia fidelidade e ajuda na guerra.", "tutor": {"alternativas": {"era o camponês que trabalhava na terra": "Quem trabalhava na terra era o servo. Vassalo era nobre.", "era quem concedia o feudo": "Quem concedia o feudo era o suserano.", "era o padre que cobrava o dízimo": "O dízimo era cobrado pela Igreja; vassalo é uma relação entre nobres."}, "pontos": ["Suserano: dá a terra. Vassalo: recebe a terra e promete lealdade e ajuda militar.", "Os dois eram nobres."], "pegadinha": "Um mesmo nobre podia ser vassalo de um senhor e suserano de outro."}}, {"id": "q4", "tipo": "mc", "enunciado": "Os <b>servos</b> eram camponeses que:", "resposta": "ficavam presos à terra e pagavam obrigações ao senhor", "alternativas": ["ficavam presos à terra e pagavam obrigações ao senhor", "podiam ser vendidos como mercadoria, separados da terra", "eram os donos dos feudos", "lutavam como cavaleiros nas guerras"], "explicacao": "O servo trabalhava a terra, não podia abandoná-la e devia várias obrigações ao senhor.", "tutor": {"alternativas": {"podiam ser vendidos como mercadoria, separados da terra": "Isso descreve a escravidão. O servo não era vendido; ele ficava ligado à terra.", "eram os donos dos feudos": "Os donos eram os senhores feudais (nobres).", "lutavam como cavaleiros nas guerras": "Cavaleiros eram nobres; os servos trabalhavam na terra."}, "pontos": ["Servo ≠ escravo: o servo não era vendido como mercadoria, mas não podia sair da terra.", "Em troca, recebia proteção e um pedaço de terra para plantar."], "pegadinha": "Servo e escravo parecem iguais, mas a prova cobra a diferença: o servo ficava preso à TERRA."}}, {"id": "q5", "tipo": "mc", "enunciado": "A <b>corveia</b> era:", "resposta": "o trabalho gratuito do servo nas terras do senhor, alguns dias por semana", "alternativas": ["o trabalho gratuito do servo nas terras do senhor, alguns dias por semana", "a parte da colheita que o servo entregava ao senhor", "a taxa para usar o moinho, o forno e outras instalações do senhor", "a décima parte da produção paga à Igreja"], "explicacao": "Corveia = dias de trabalho de graça nas terras do senhor.", "tutor": {"alternativas": {"a parte da colheita que o servo entregava ao senhor": "Entregar parte da colheita era a talha.", "a taxa para usar o moinho, o forno e outras instalações do senhor": "Essa taxa se chamava banalidades.", "a décima parte da produção paga à Igreja": "Essa era o dízimo."}, "pontos": ["Corveia: trabalho gratuito. Talha: parte da produção. Banalidades: taxa de uso. Dízimo: 10% para a Igreja."], "pegadinha": "As quatro obrigações aparecem juntas na prova; associe cada nome a uma ação."}}, {"id": "q6", "tipo": "mc", "enunciado": "Na sociedade feudal, qual grupo era responsável por <b>rezar</b>?", "resposta": "o clero", "alternativas": ["o clero", "a nobreza", "os servos", "os burgueses"], "explicacao": "A sociedade se dividia em quem reza (clero), quem guerreia (nobreza) e quem trabalha (servos).", "tutor": {"alternativas": {"a nobreza": "A nobreza era quem guerreava e protegia.", "os servos": "Os servos eram quem trabalhava na terra.", "os burgueses": "Burgueses eram comerciantes das cidades, que só ganham força no fim da Idade Média."}, "pontos": ["Clero: reza. Nobreza: guerreia. Servos: trabalham."], "pegadinha": "Burguês não faz parte das três ordens: ele surge depois, com o crescimento das cidades."}}, {"id": "q7", "tipo": "mc", "enunciado": "Por que a sociedade feudal é chamada de <b>estamental</b>?", "resposta": "porque a posição de cada pessoa era definida pelo nascimento, quase sem mudança", "alternativas": ["porque a posição de cada pessoa era definida pelo nascimento, quase sem mudança", "porque todos tinham os mesmos direitos", "porque o dinheiro definia o grupo social", "porque era governada por um parlamento eleito"], "explicacao": "Estamental: nasceu servo, morria servo; nasceu nobre, morria nobre.", "tutor": {"alternativas": {"porque todos tinham os mesmos direitos": "Era o contrário: cada grupo tinha direitos e deveres diferentes.", "porque o dinheiro definia o grupo social": "Na sociedade feudal, o que contava era o nascimento, não o dinheiro.", "porque era governada por um parlamento eleito": "Não havia eleições; o poder estava com os senhores e o rei."}, "pontos": ["Sociedade estamental: pouquíssima mobilidade social.", "A posição vinha do nascimento."], "pegadinha": "Entrar para o clero era uma das poucas formas de mudar de grupo."}}, {"id": "q8", "tipo": "mc", "enunciado": "Qual instituição tinha grande poder na Idade Média, possuía muitas terras e guardava livros nos mosteiros?", "resposta": "a Igreja Católica", "alternativas": ["a Igreja Católica", "o Senado romano", "as pólis gregas", "os bancos"], "explicacao": "A Igreja Católica era a instituição mais poderosa: religião, terras, educação e cultura.", "tutor": {"alternativas": {"o Senado romano": "O Senado é de Roma Antiga, antes da Idade Média.", "as pólis gregas": "Pólis são da Grécia Antiga.", "os bancos": "Bancos só ganham força no fim da Idade Média e na Idade Moderna."}, "pontos": ["Igreja: maior proprietária de terras e centro da cultura.", "Monges copistas copiavam livros à mão nos mosteiros."], "pegadinha": "A Igreja tinha poder espiritual E material (terras e riqueza)."}}, {"id": "q9", "tipo": "mc", "enunciado": "A economia feudal era principalmente:", "resposta": "agrária, voltada ao próprio consumo, com pouco comércio", "alternativas": ["agrária, voltada ao próprio consumo, com pouco comércio", "industrial, com fábricas e máquinas", "baseada em comércio marítimo intenso", "baseada na mineração de ouro"], "explicacao": "O feudo produzia quase tudo o que consumia; quase não havia comércio nem moeda.", "tutor": {"alternativas": {"industrial, com fábricas e máquinas": "Fábricas só aparecem muitos séculos depois, na Revolução Industrial.", "baseada em comércio marítimo intenso": "O comércio era fraco; cada feudo produzia quase tudo de que precisava.", "baseada na mineração de ouro": "A riqueza vinha da terra e da agricultura, não do ouro."}, "pontos": ["Economia feudal: agrária e autossuficiente.", "Pouco uso de moeda; trocas diretas."], "pegadinha": "Autossuficiente = produz o que consome. É a palavra-chave da economia feudal."}}, {"id": "q10", "tipo": "mc", "enunciado": "No feudalismo, o poder político era <b>descentralizado</b>. Isso quer dizer que:", "resposta": "cada senhor feudal mandava em suas terras, e o rei tinha pouco poder", "alternativas": ["cada senhor feudal mandava em suas terras, e o rei tinha pouco poder", "o rei controlava tudo sozinho", "o povo votava nos governantes", "a Igreja não tinha nenhuma influência"], "explicacao": "Descentralizado = poder espalhado entre muitos senhores feudais.", "tutor": {"alternativas": {"o rei controlava tudo sozinho": "Isso seria poder centralizado, que só volta no fim da Idade Média.", "o povo votava nos governantes": "Não havia eleições no feudalismo.", "a Igreja não tinha nenhuma influência": "A Igreja tinha enorme influência."}, "pontos": ["Feudalismo: poder descentralizado, nas mãos dos senhores.", "Rei fraco; cada senhor fazia as leis no seu feudo."], "pegadinha": "Centralizar é juntar o poder num só lugar; descentralizar é espalhar."}}]$j$::jsonb, now()
from turmas t join escolas e on e.id = t.escola_id
where e.codigo = 'PILOTO' and t.nome = '6º ano A'
  and not exists (select 1 from materiais m where m.turma_id = t.id and m.titulo = 'Idade Média e feudalismo');
